package net.fabricmc.fabric.api.event.player;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;

/** Fabric API callback (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
@FunctionalInterface
public interface AttackBlockCallback {
    Event<AttackBlockCallback> EVENT = EventFactory.createArrayBacked(AttackBlockCallback.class, ls -> (player, world, hand, pos, direction) -> { for (AttackBlockCallback l : ls) { InteractionResult r = l.interact(player, world, hand, pos, direction); if (r != InteractionResult.PASS) return r; } return InteractionResult.PASS; });

    InteractionResult interact(Player player, Level world, InteractionHand hand, BlockPos pos, Direction direction);
}
